const T2_NEG_COVERAGE_MAP_PATH = abspath(ARGS[15])
const T2_NEG_COVERAGE_MAP_SHA256 = lowercase(ARGS[16])
const T2_NEG_COVERAGE_MAP_BYTES = read(T2_NEG_COVERAGE_MAP_PATH)
bytes2hex(SHA.sha256(T2_NEG_COVERAGE_MAP_BYTES)) ==
    T2_NEG_COVERAGE_MAP_SHA256 || error(:negative_coverage_map_sha256_mismatch)
const T2_NEG_COVERAGE_MAP = JSON3.read(String(T2_NEG_COVERAGE_MAP_BYTES))
const T2_NEG_DRIVER_SOURCE_PATH =
    "test/GenomeV5/Integration/VNextT2FormalIndependentR1/actual_formal_negative_driver_r5.jl"
const T2_NEG_SOURCE_SITE_ROWS = filter(row ->
    String(row.path) == T2_NEG_DRIVER_SOURCE_PATH,
    T2_NEG_COVERAGE_MAP.successor_assertion_sites)
isempty(T2_NEG_SOURCE_SITE_ROWS) && error(:negative_source_site_map_empty)
const T2_NEG_SITE_ID_BY_LINE = Dict{Int,String}()
for row in T2_NEG_SOURCE_SITE_ROWS
    line = Int(row.line)
    site_id = String(row.id)
    haskey(T2_NEG_SITE_ID_BY_LINE, line) &&
        error((:negative_source_site_line_duplicate, line))
    T2_NEG_SITE_ID_BY_LINE[line] = site_id
end
const T2_NEG_LAST_SITE_TESTSET = Ref{Any}(nothing)

mutable struct T2NegAssertionSiteTestSet <: Test.AbstractTestSet
    inner::Test.DefaultTestSet
    hits::Dict{String,Int}
    unmapped::Vector{String}
end

function T2NegAssertionSiteTestSet(desc; kwargs...)
    inner = Test.DefaultTestSet(desc; kwargs...)
    hits = Dict{String,Int}(String(row.id) => 0
        for row in T2_NEG_SOURCE_SITE_ROWS)
    result = T2NegAssertionSiteTestSet(inner, hits, String[])
    T2_NEG_LAST_SITE_TESTSET[] = result
    result
end

function _t2_neg_is_target_source(file)
    normalized = lowercase(replace(string(file), '\\' => '/'))
    basename = split(normalized, '/') |> last
    basename in ("actual_formal_negative_driver_r5.jl",
                 "actual_formal_negative_driver_r3")
end

function Test.record(testset::T2NegAssertionSiteTestSet,
                     result::Test.Result)
    source = hasfield(typeof(result), :source) ? getfield(result, :source) : nothing
    if source isa LineNumberNode && _t2_neg_is_target_source(source.file)
        site_id = get(T2_NEG_SITE_ID_BY_LINE, source.line, nothing)
        if site_id === nothing
            push!(testset.unmapped,
                "$(source.file):$(source.line)")
        else
            testset.hits[site_id] += 1
        end
    end
    _t2_neg_authority_progress_note_result!(result); Test.record(testset.inner, result)
end

function Test.record(testset::T2NegAssertionSiteTestSet,
                     child::Test.AbstractTestSet)
    Test.record(testset.inner, child)
end

function Test.finish(testset::T2NegAssertionSiteTestSet)
    Test.finish(testset.inner)
    isempty(testset.unmapped) || error((:unmapped_negative_assertion_sources,
        testset.unmapped))
    testset
end

function _t2_neg_assertion_site_hit_receipt(phase)
    testset = T2_NEG_LAST_SITE_TESTSET[]
    testset isa T2NegAssertionSiteTestSet ||
        error(:negative_assertion_site_testset_missing)
    (schema="vnext-t2-source-site-hit-receipt-r1",
     phase=String(phase),
     source_path=T2_NEG_DRIVER_SOURCE_PATH,
     source_sha256=bytes2hex(SHA.sha256(read(@__FILE__))),
     coverage_map_sha256=T2_NEG_COVERAGE_MAP_SHA256,
     hit_count=sum(values(testset.hits)),
     hit_counts=Dict(sort(collect(testset.hits); by=first)),
     unmapped_sources=Tuple(testset.unmapped))
end

function _t2_neg_stage_event(label::String; elapsed_ns=nothing,
        detail::String="")
    suffix = elapsed_ns === nothing ? "" : "\telapsed_ns=$(elapsed_ns)"
    isempty(detail) || (suffix *= "\tdetail=$(detail)")
    line = "$(label)\tpid=$(getpid())\ttime_ns=$(time_ns())$(suffix)"
    open(T2_NEG_R5_STAGE_TRACE, "a") do io
        println(io, line)
        flush(io)
    end
    println("VNEXT_T2_NEGATIVE_STAGE=" * line)
    flush(stdout)
    nothing
end

function _t2_neg_stage_begin(label::String)
    _t2_neg_stage_event(label * ".begin")
    time_ns()
end

function _t2_neg_stage_end(label::String, started::UInt64; detail::String="")
    _t2_neg_stage_event(label * ".end",
        elapsed_ns=time_ns() - started, detail=detail)
end

