function _t2_neg_write_summary(path, summary)
    ispath(path) && error(:negative_summary_already_exists)
    open(path, "w") do io
        write(io, FusionConceptAI.canonical_json(summary) * "\n")
        flush(io)
    end
end

@noinline Base.@nospecializeinfer function _t2_neg_run_baseline(
        manifest_path, manifest_sha, verification_path, verification_sha,
        candidate_path, candidate_sha, package_path, package_sha,
        context_path, context_create, authorization_path,
        authorization_create, output_dir)
    _t2_neg_stage_event("baseline_function_body_first")
    context_create == "create" || error(:baseline_context_create_token_invalid)
    authorization_create == "create" ||
        error(:baseline_authorization_create_token_invalid)
    ispath(authorization_path) && error(:baseline_authorization_preexists)
    observations_path = joinpath(output_dir, "observations.jsonl")
    summary_path = joinpath(output_dir, "summary.json")
    ispath(observations_path) && error(:negative_observations_already_exist)
    ispath(summary_path) && error(:negative_summary_already_exists)
    authorities = _t2_neg_read_authorities(manifest_path, manifest_sha,
        verification_path, verification_sha, candidate_path, candidate_sha,
        package_path, package_sha)
    live = _t2_neg_material_from_original(authorities, manifest_sha,
        verification_sha)
    started = _t2_neg_stage_begin("five_consumer_baseline")
    result = FusionConceptAI.vnext_t2_rebind_identity_receipts_v2(live.build)
    _t2_neg_stage_end("five_consumer_baseline", started,
        detail="status=$(result.status)")
    observed_case_ids = String[]
    test_error = nothing
    stream = open(observations_path, "w")
    wire_before = _t2_neg_sha256(FusionConceptAI.copy_bytes(live.package.wire))
    context_receipt = nothing
    try
        assertion_started = _t2_neg_stage_begin("post_consumer_require_baseline"); @testset T2NegAssertionSiteTestSet "VNext T2 actual formal baseline producer" begin
            _t2_neg_require_baseline!(stream, live.build, result,
                live.material, live.build.input.package.package_hash)
            push!(observed_case_ids, "ACTUAL_BASELINE_POSITIVE")
        end; _t2_neg_stage_end("post_consumer_require_baseline", assertion_started, detail="status=complete"); context_build_started = _t2_neg_stage_begin("baseline_context_construction")
        context = _t2_neg_context_body(live, result, authorities,
            manifest_sha, verification_sha, candidate_sha, package_sha)
        _t2_neg_stage_end("baseline_context_construction", context_build_started, detail="status=constructed"); context_write_started = _t2_neg_stage_begin("baseline_context_serialization"); context_receipt = _t2_neg_write_context(context_path, context); _t2_neg_stage_end("baseline_context_serialization", context_write_started, detail="bytes=$(context_receipt.bytes)")
    catch error
        test_error = error
    finally
        close(stream)
        package_after = read(package_path)
        candidate_after = read(candidate_path)
        site_hits = _t2_neg_assertion_site_hit_receipt(
            "actual_formal_baseline")
        summary = (schema="vnext-t2-independent-actual-baseline-summary-r3",
            driver_version=T2_NEG_DRIVER_VERSION,
            status=test_error === nothing ? :pass : :fail,
            observed_case_ids=Tuple(observed_case_ids),
            observed_case_count=length(observed_case_ids),
            producer_package_sha256=authorities.package_raw.sha256,
            producer_package_unchanged=package_after ==
                authorities.package_raw.bytes,
            candidate_receipt_sha256=authorities.candidate_raw.sha256,
            candidate_receipt_unchanged=candidate_after ==
                authorities.candidate_raw.bytes,
            package_wire_direct_sha256_before=wire_before,
            package_wire_direct_sha256_after=_t2_neg_sha256(
                FusionConceptAI.copy_bytes(live.package.wire)),
            package_wire_unchanged=wire_before == _t2_neg_sha256(
                FusionConceptAI.copy_bytes(live.package.wire)),
            source_revalidation_status=live.source_validation.status,
            build_input_hash=live.build.input.input_hash,
            final_package_fingerprint=_t2_neg_package_fingerprint(live.package),
            final_ledger_fingerprint=_t2_neg_ledger_fingerprint(result.ledger),
            context_receipt=context_receipt,
            assertion_site_hit_receipt_schema=site_hits.schema,
            assertion_site_hit_phase=site_hits.phase,
            assertion_site_hit_source_path=site_hits.source_path,
            assertion_site_hit_source_sha256=site_hits.source_sha256,
            assertion_site_hit_coverage_map_sha256=
                site_hits.coverage_map_sha256,
            assertion_site_hit_count_observed=site_hits.hit_count,
            assertion_site_hit_counts=site_hits.hit_counts,
            unmapped_assertion_sources=site_hits.unmapped_sources,
            observation_file_sha256=_t2_neg_sha256(read(observations_path)),
            formal_gate_evidence_kind=:formal_t1_actual,
            formal_t2_accepted=false, physical_acceptance=false,
            scientific_acceptance=false,
            actual_model_attestation="unavailable",
            error_type=test_error === nothing ? nothing :
                string(typeof(test_error)),
            error_text=test_error === nothing ? nothing :
                sprint(showerror, test_error))
        _t2_neg_write_summary(summary_path, summary); _t2_neg_stage_event("baseline_summary_complete", detail="status=$(summary.status)")
        println("VNEXT_T2_NEGATIVE_BASELINE_SUMMARY=" *
            FusionConceptAI.canonical_json(summary))
        flush(stdout)
    end
    test_error === nothing || throw(test_error)
    println("VNEXT_T2_ACTUAL_FORMAL_BASELINE=PASS")
    flush(stdout)
    nothing
end

@noinline Base.@nospecializeinfer function _t2_neg_run_shard(
        mode::String, @nospecialize(group), manifest_path, manifest_sha,
        verification_path, verification_sha, candidate_path, candidate_sha,
        package_path, package_sha, context_path, context_sha,
        authorization_path, authorization_sha, output_dir)
    _t2_neg_stage_event("shard_function_body_first", detail=mode)
    observations_path = joinpath(output_dir, "observations.jsonl")
    summary_path = joinpath(output_dir, "summary.json")
    T2_NEG_R5_CASE_PROGRESS_PATH[] = nothing
    mode == "authority" && _t2_neg_authority_progress_init!(
        output_dir, something(T2_NEG_R5_SELECTED_AUTHORITY_CASE[], ""))
    ispath(observations_path) && error(:negative_observations_already_exist)
    ispath(summary_path) && error(:negative_summary_already_exists)
    authorities = _t2_neg_read_authorities(manifest_path, manifest_sha,
        verification_path, verification_sha, candidate_path, candidate_sha,
        package_path, package_sha)
    rebuilt = _t2_neg_load_and_rebuild_context(context_path, context_sha,
        authorization_path, authorization_sha, authorities, manifest_sha,
        verification_sha, candidate_sha, package_sha)
    observed_case_ids = String[]
    test_error = nothing
    stream = open(observations_path, "w")
    package_wire_before = _t2_neg_sha256(
        FusionConceptAI.copy_bytes(rebuilt.package.wire))
    prior_before = _t2_neg_ledger_fingerprint(rebuilt.result.ledger)
    transport_observation_path = joinpath(output_dir,
        "context_transport_observation.json")
    _t2_neg_write_transport_observation(transport_observation_path, mode,
        rebuilt.transport_facts)
    try
        @testset T2NegAssertionSiteTestSet "VNext T2 actual formal shard $(mode)" begin
            if mode != "authority" ||
                    T2_NEG_R5_SELECTED_AUTHORITY_CASE[] ==
                        first(T2_NEG_R5_PROGRESS_CASE_ORDER)
                _t2_neg_require_transport!(rebuilt.transport_facts)
            end
            started = _t2_neg_stage_begin("attack_group_$(mode)")
            Base.invokelatest(group, stream, observed_case_ids,
                rebuilt.baseline, rebuilt)
            _t2_neg_stage_end("attack_group_$(mode)", started,
                detail="cases=$(length(observed_case_ids))")
        end
        expected_case_ids = mode == "authority" &&
            T2_NEG_R5_SELECTED_AUTHORITY_CASE[] !== nothing ?
            [T2_NEG_R5_SELECTED_AUTHORITY_CASE[]] :
            T2_NEG_SHARD_SUMMARY_IDS[mode]
        observed_case_ids == expected_case_ids ||
            error((:negative_shard_case_inventory_mismatch, mode,
                observed_case_ids, expected_case_ids))
    catch error
        test_error = error
    finally
        close(stream)
        package_after = read(package_path)
        candidate_after = read(candidate_path)
        context_after = read(context_path)
        prior_after = _t2_neg_ledger_fingerprint(rebuilt.result.ledger)
        phase_name = "actual_formal_$(mode)"
        site_hits = _t2_neg_assertion_site_hit_receipt(phase_name)
        summary = (schema="vnext-t2-independent-actual-negative-shard-summary-r5",
            driver_version=T2_NEG_DRIVER_VERSION, shard=mode,
            status=test_error === nothing ? :pass : :fail,
            observed_case_ids=Tuple(observed_case_ids),
            observed_case_count=length(observed_case_ids),
            producer_package_sha256=authorities.package_raw.sha256,
            producer_package_unchanged=package_after ==
                authorities.package_raw.bytes,
            candidate_receipt_sha256=authorities.candidate_raw.sha256,
            candidate_receipt_unchanged=candidate_after ==
                authorities.candidate_raw.bytes,
            context_sha256=rebuilt.context_raw.sha256,
            context_unchanged=_t2_neg_sha256(context_after) ==
                rebuilt.context_raw.sha256,
            source_revalidation_status=rebuilt.source_validation.status,
            rebuilt_input_full_content_join=true,
            package_wire_direct_sha256_before=package_wire_before,
            package_wire_direct_sha256_after=_t2_neg_sha256(
                FusionConceptAI.copy_bytes(rebuilt.package.wire)),
            package_wire_unchanged=package_wire_before == _t2_neg_sha256(
                FusionConceptAI.copy_bytes(rebuilt.package.wire)),
            prior_ledger_fingerprint_before=prior_before,
            prior_ledger_fingerprint_after=prior_after,
            prior_ledger_unchanged=prior_before == prior_after,
            context_transport_observation_sha256=
                _t2_neg_sha256(read(transport_observation_path)),
            authority_case_progress_path=mode == "authority" ?
                "case_progress.jsonl" : nothing,
            authority_case_progress_sha256=mode == "authority" ?
                _t2_neg_sha256(read(joinpath(output_dir, "case_progress.jsonl"))) :
                nothing,
            assertion_site_hit_receipt_schema=site_hits.schema,
            assertion_site_hit_phase=site_hits.phase,
            assertion_site_hit_source_path=site_hits.source_path,
            assertion_site_hit_source_sha256=site_hits.source_sha256,
            assertion_site_hit_coverage_map_sha256=
                site_hits.coverage_map_sha256,
            assertion_site_hit_count_observed=site_hits.hit_count,
            assertion_site_hit_counts=site_hits.hit_counts,
            unmapped_assertion_sources=site_hits.unmapped_sources,
            observation_file_sha256=_t2_neg_sha256(read(observations_path)),
            formal_gate_evidence_kind=:formal_t1_actual,
            formal_t2_accepted=false, physical_acceptance=false,
            scientific_acceptance=false,
            actual_model_attestation="unavailable",
            error_type=test_error === nothing ? nothing :
                string(typeof(test_error)),
            error_text=test_error === nothing ? nothing :
                sprint(showerror, test_error))
        _t2_neg_write_summary(summary_path, summary)
        println("VNEXT_T2_NEGATIVE_SHARD_SUMMARY=" *
            FusionConceptAI.canonical_json(summary))
        flush(stdout)
    end
    test_error === nothing || throw(test_error)
    println("VNEXT_T2_ACTUAL_FORMAL_SHARD=PASS mode=$(mode)")
    flush(stdout)
    nothing
end


const T2_NEG_R5_CASE_PROGRESS_SCHEMA =
    "vnext-t2-authority-case-progress-r2"
const T2_NEG_R5_CASE_PROGRESS_PATH = Ref{Union{Nothing,String}}(nothing)
const T2_NEG_R5_SELECTED_AUTHORITY_CASE = Ref{Union{Nothing,String}}(nothing)
const T2_NEG_R5_ACTIVE_CASE = Ref{Union{Nothing,String}}(nothing)
const T2_NEG_R5_ACTIVE_HITS = Ref{Dict{String,Int}}(Dict{String,Int}())
const T2_NEG_R5_ACTIVE_RESULTS = Ref{Dict{String,Int}}(Dict{String,Int}())
const T2_NEG_R5_ACTIVE_UNMAPPED = Ref(0)
const T2_NEG_R5_COMPLETED_CASES = Ref(0)
const T2_NEG_R5_PROGRESS_CASE_ORDER = [
    "PARENT_STALE", "PARENT_FOREIGN", "G3_STALE", "G3_FOREIGN",
    "ACTUAL_FOREIGN_SCENARIO", "ACTUAL_TYPED_ABSENCE",
    "ACTUAL_FORMAL_GATE_REJECTION",
    "ACTUAL_FORMAL_GATE_REJECTION_NO_PRIOR",
    "ACTUAL_DUPLICATE_INVOCATION",
]

function _t2_neg_authority_progress_append!(row::Dict{String,Any})
    path = T2_NEG_R5_CASE_PROGRESS_PATH[]
    path === nothing && error(:authority_case_progress_not_initialized)
    line = FusionConceptAI.canonical_json(row)
    open(path, "a") do io
        println(io, line)
        flush(io)
    end
    println("VNEXT_T2_NEGATIVE_CASE_PROGRESS=" * line)
    flush(stdout)
    nothing
end

function _t2_neg_authority_progress_init!(output_dir, case_id::String)
    path = joinpath(output_dir, "case_progress.jsonl")
    ispath(path) && error(:authority_case_progress_already_exists)
    T2_NEG_R5_CASE_PROGRESS_PATH[] = path
    T2_NEG_R5_ACTIVE_CASE[] = nothing
    T2_NEG_R5_COMPLETED_CASES[] = 0
    site_ids = sort!([String(row.id) for row in T2_NEG_SOURCE_SITE_ROWS])
    row = Dict{String,Any}(
        "schema" => T2_NEG_R5_CASE_PROGRESS_SCHEMA,
        "event" => "header",
        "phase" => "actual_formal_authority",
        "driver_version" => T2_NEG_DRIVER_VERSION,
        "source_path" => T2_NEG_DRIVER_SOURCE_PATH,
        "source_sha256" => bytes2hex(SHA.sha256(read(@__FILE__))),
        "coverage_map_sha256" => T2_NEG_COVERAGE_MAP_SHA256,
        "site_ids" => site_ids,
        "expected_case_ids" => [case_id],
        "selected_case_id" => case_id,
        "status" => "progress_only",
        "actual_hit_counts_are_measured" => true,
        "formal_t2_accepted" => false,
    )
    open(path, "w") do io
        println(io, FusionConceptAI.canonical_json(row))
        flush(io)
    end
    println("VNEXT_T2_NEGATIVE_CASE_PROGRESS=" *
        FusionConceptAI.canonical_json(row))
    flush(stdout)
    nothing
end

function _t2_neg_authority_progress_note_result!(result::Test.Result)
    T2_NEG_R5_ACTIVE_CASE[] === nothing && return nothing
    counts = T2_NEG_R5_ACTIVE_RESULTS[]
    key = result isa Test.Pass ? "pass" :
        result isa Test.Fail ? "fail" :
        result isa Test.Error ? "error" :
        result isa Test.Broken ? "broken" : "other"
    counts[key] = get(counts, key, 0) + 1
    nothing
end

function _t2_neg_authority_case_selected(case_id::String)
    selected = T2_NEG_R5_SELECTED_AUTHORITY_CASE[]
    selected === nothing || selected == case_id
end

function _t2_neg_authority_case_begin!(case_id::String)
    T2_NEG_R5_CASE_PROGRESS_PATH[] === nothing &&
        error(:authority_case_progress_not_initialized)
    T2_NEG_R5_ACTIVE_CASE[] === nothing ||
        error((:authority_case_progress_nested, T2_NEG_R5_ACTIVE_CASE[]))
    expected_ids = T2_NEG_R5_SELECTED_AUTHORITY_CASE[] === nothing ?
        T2_NEG_R5_PROGRESS_CASE_ORDER :
        [T2_NEG_R5_SELECTED_AUTHORITY_CASE[]]
    next_sequence = T2_NEG_R5_COMPLETED_CASES[] + 1
    next_sequence <= length(expected_ids) &&
        expected_ids[next_sequence] == case_id ||
        error((:authority_case_progress_case_order, next_sequence, case_id))
    testset = T2_NEG_LAST_SITE_TESTSET[]
    testset isa T2NegAssertionSiteTestSet ||
        error(:authority_case_progress_testset_missing)
    T2_NEG_R5_ACTIVE_CASE[] = case_id
    T2_NEG_R5_ACTIVE_HITS[] = Dict{String,Int}(testset.hits)
    T2_NEG_R5_ACTIVE_RESULTS[] = Dict{String,Int}(
        "pass" => 0, "fail" => 0, "error" => 0, "broken" => 0, "other" => 0)
    T2_NEG_R5_ACTIVE_UNMAPPED[] = length(testset.unmapped)
    _t2_neg_authority_progress_append!(Dict{String,Any}(
        "schema" => T2_NEG_R5_CASE_PROGRESS_SCHEMA,
        "event" => "case_begin",
        "phase" => "actual_formal_authority",
        "selected_case_id" => T2_NEG_R5_SELECTED_AUTHORITY_CASE[],
        "sequence" => next_sequence,
        "case_id" => case_id,
        "monotonic_time_ns" => time_ns(),
        "status" => "running",
        "formal_t2_accepted" => false,
    ))
    nothing
end

function _t2_neg_authority_case_complete!(case_id::String)
    T2_NEG_R5_ACTIVE_CASE[] == case_id ||
        error((:authority_case_progress_end_without_begin, case_id))
    testset = T2_NEG_LAST_SITE_TESTSET[]
    testset isa T2NegAssertionSiteTestSet ||
        error(:authority_case_progress_testset_missing)
    before = T2_NEG_R5_ACTIVE_HITS[]
    site_counts = Dict{String,Int}()
    for row in T2_NEG_SOURCE_SITE_ROWS
        id = String(row.id)
        delta = get(testset.hits, id, 0) - get(before, id, 0)
        delta >= 0 || error((:authority_case_progress_negative_delta, id, delta))
        site_counts[id] = delta
    end
    result_counts = Dict{String,Int}(T2_NEG_R5_ACTIVE_RESULTS[])
    result_total = sum(values(result_counts))
    hit_total = sum(values(site_counts))
    unmapped_count = length(testset.unmapped) - T2_NEG_R5_ACTIVE_UNMAPPED[]
    unmapped_count >= 0 || error(:authority_case_progress_unmapped_counter_regressed)
    no_failed_test_results = sum(result_counts[k] for k in
        ("fail", "error", "broken", "other")) == 0
    row = Dict{String,Any}(
        "schema" => T2_NEG_R5_CASE_PROGRESS_SCHEMA,
        "event" => "case_complete",
        "phase" => "actual_formal_authority",
        "selected_case_id" => T2_NEG_R5_SELECTED_AUTHORITY_CASE[],
        "sequence" => T2_NEG_R5_COMPLETED_CASES[] + 1,
        "case_id" => case_id,
        "monotonic_time_ns" => time_ns(),
        "case_completed" => true,
        "assertion_result_count_observed" => result_total,
        "assertion_result_counts_observed" => result_counts,
        "assertion_site_hit_count_observed" => hit_total,
        "assertion_site_hit_counts_observed" => site_counts,
        "unmapped_assertion_source_count_observed" => unmapped_count,
        "all_recorded_assertions_passed_observed" => no_failed_test_results,
        "status" => no_failed_test_results && unmapped_count == 0 &&
            hit_total == result_total ? "completed" : "completed_with_test_or_mapping_issue",
        "formal_t2_accepted" => false,
    )
    _t2_neg_authority_progress_append!(row)
    T2_NEG_R5_COMPLETED_CASES[] += 1
    T2_NEG_R5_ACTIVE_CASE[] = nothing
    nothing
end

_t2_neg_stage_event("definitions_ready")

mode_argument = ARGS[1]
mode = mode_argument
if startswith(mode_argument, "authority-case:")
    selected_case = mode_argument[length("authority-case:") + 1:end]
    selected_case in T2_NEG_R5_PROGRESS_CASE_ORDER ||
        error((:unknown_authority_case, selected_case))
    mode = "authority"
    T2_NEG_R5_SELECTED_AUTHORITY_CASE[] = selected_case
end
manifest_path, manifest_sha = abspath(ARGS[2]), lowercase(ARGS[3])
verification_path, verification_sha = abspath(ARGS[4]), lowercase(ARGS[5])
candidate_path, candidate_sha = abspath(ARGS[6]), lowercase(ARGS[7])
package_path, package_sha = abspath(ARGS[8]), lowercase(ARGS[9])
context_path, context_sha = abspath(ARGS[10]), lowercase(ARGS[11])
authorization_path, authorization_sha = abspath(ARGS[12]), lowercase(ARGS[13])
output_dir = abspath(ARGS[14])

_t2_neg_stage_event("dispatch_before", detail=mode_argument)
if mode == "baseline"
    Base.invokelatest(_t2_neg_run_baseline, manifest_path, manifest_sha,
        verification_path, verification_sha, candidate_path, candidate_sha,
        package_path, package_sha, context_path, context_sha,
        authorization_path, authorization_sha, output_dir)
else
    group = mode == "preflight" ? _t2_neg_group_preflight! :
        mode == "authority" ? _t2_neg_group_authority! :
        mode == "fault_n10" ? _t2_neg_group_fault_n10! :
        mode == "t1_handoff" ? _t2_neg_group_t1_handoff! :
        error((:unknown_negative_shard, mode))
    Base.invokelatest(_t2_neg_run_shard, mode, group, manifest_path,
        manifest_sha, verification_path, verification_sha, candidate_path,
        candidate_sha, package_path, package_sha, context_path, context_sha,
        authorization_path, authorization_sha, output_dir)
end
_t2_neg_stage_event("dispatch_after", detail=mode_argument)
